//! Embedded columns: a `VECTOR(n)` column declared as the embedding of an
//! expression over its row, in `CREATE TABLE` and `ALTER TABLE`:
//!
//! ```sql
//! ALTER TABLE products ADD COLUMN embedding VECTOR(384)
//!   GENERATED BY EMBEDDING(CONCAT_WS(' ', name, description))
//!   USING MODEL 'local:bge-small' [ON CHANGE ASYNC | SYNC]
//!   [WITH (max_input_tokens = 256)];
//! ```
//!
//! This module is the statement side, text only: [`parse`] finds the
//! clauses (and, in `ALTER TABLE`, the specifications that touch a
//! column, so the gateway can check them against embedded columns), and
//! [`column_defs`] writes what MariaDB stores for one:
//!
//! | Column | Definition |
//! |---|---|
//! | `<c>` | `VECTOR(n) NULL DEFAULT NULL`: the vectors, `NULL` until filled |
//! | `_sprig_emb_<c>_src` | `MEDIUMTEXT GENERATED ALWAYS AS (<source>) VIRTUAL INVISIBLE`, with the column's settings as a comment ([`Meta`]) |
//! | `_sprig_emb_<c>_hash` | `BINARY(16) NULL INVISIBLE`: `UNHEX(MD5(source))` of the text last embedded |
//!
//! MariaDB checks the source as it checks any generated column: it must be
//! deterministic and name only the row's own columns, and a column it uses
//! can't be dropped while the embedded column exists. A re-embedding (a new
//! model or source) adds a shadow generation `_sprig_emb_<c>_g<n>` with its
//! own `_hash` (and `_src`, when the source changed), which a cutover
//! renames into place ([`cutover_sql`]).
//!
//! `SHOW CREATE TABLE` reads the clause back from the comment
//! ([`show_create`]) before the name layer hides the `_sprig_` columns.

use std::borrow::Cow;
use std::fmt::Write as _;
use std::ops::Range;

use serde_json::{Value, json};

use crate::lex::{self, LexOptions, Token, TokenKind};

/// The name prefix of an embedded column's hidden columns.
pub const PREFIX: &str = "_sprig_emb_";

/// The longest name an embedded column may have: its hidden columns'
/// names (`_sprig_emb_<c>_g<n>_hash`) must fit MariaDB's 64 characters.
pub const MAX_COLUMN: usize = 40;

/// What starts the hidden source column's comment.
pub const COMMENT_TAG: &str = "sprig:embedding ";

/// The largest `max_input_tokens`.
pub const MAX_INPUT_TOKENS: u32 = 8192;

/// The hidden source column of `column`'s generation `shadow` (`None`: the
/// current one).
#[must_use]
pub fn src_column(column: &str, shadow: Option<u32>) -> String {
    match shadow {
        None => format!("{PREFIX}{column}_src"),
        Some(g) => format!("{PREFIX}{column}_g{g}_src"),
    }
}

/// The hidden hash column of `column`'s generation `shadow`.
#[must_use]
pub fn hash_column(column: &str, shadow: Option<u32>) -> String {
    match shadow {
        None => format!("{PREFIX}{column}_hash"),
        Some(g) => format!("{PREFIX}{column}_g{g}_hash"),
    }
}

/// The vector column of `column`'s generation `shadow`: the column itself
/// for the current one, `_sprig_emb_<c>_g<n>` for a shadow.
#[must_use]
pub fn vector_column(column: &str, shadow: Option<u32>) -> String {
    match shadow {
        None => column.to_owned(),
        Some(g) => format!("{PREFIX}{column}_g{g}"),
    }
}

/// When the vector is computed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Mode {
    /// By the embedding worker, after the write commits (the default).
    Async,
    /// In the writing statement.
    Sync,
}

impl Mode {
    /// `async` or `sync`.
    #[must_use]
    pub fn as_str(self) -> &'static str {
        match self {
            Mode::Async => "async",
            Mode::Sync => "sync",
        }
    }

    /// From [`Mode::as_str`].
    #[must_use]
    pub fn parse(s: &str) -> Option<Self> {
        match s {
            "async" => Some(Mode::Async),
            "sync" => Some(Mode::Sync),
            _ => None,
        }
    }
}

/// One `GENERATED BY EMBEDDING` column definition.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Clause {
    /// The column.
    pub column: String,
    /// `VECTOR(n)`'s `n`.
    pub dim: u32,
    /// The source expression as written.
    pub source: String,
    /// The model alias.
    pub model: String,
    /// `ON CHANGE`.
    pub mode: Mode,
    /// `WITH (max_input_tokens = n)`.
    pub max_input_tokens: Option<u32>,
    /// The whole column definition in the statement (from the column name;
    /// in `ALTER TABLE`, from `ADD` or `MODIFY`).
    pub span: Range<usize>,
}

/// What an `ALTER TABLE` specification touching a column does to it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Touch {
    /// `DROP [COLUMN] c`.
    Drop,
    /// `CHANGE [COLUMN] c ...`.
    Change,
    /// `MODIFY [COLUMN] c ...` without an embedding clause.
    Modify,
    /// `RENAME COLUMN c TO ...`.
    Rename,
    /// `ALTER [COLUMN] c ...`.
    Alter,
}

/// One specification of an `ALTER TABLE`, as far as embedded columns care.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Spec {
    /// `ADD [COLUMN] c VECTOR(n) GENERATED BY EMBEDDING ...`.
    Add(Clause),
    /// `MODIFY [COLUMN] c VECTOR(n) GENERATED BY EMBEDDING ...`: a new
    /// model or source for an embedded column.
    Modify(Clause),
    /// A specification that touches column `column`.
    Touch {
        /// What it does.
        kind: Touch,
        /// The column.
        column: String,
        /// The specification's text.
        span: Range<usize>,
    },
}

/// A statement with embedding clauses, or an `ALTER TABLE` touching
/// columns.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Stmt {
    /// `CREATE TABLE` with embedded columns.
    CreateTable {
        /// The database, when the statement names one.
        db: Option<String>,
        /// The table.
        table: String,
        /// The embedded columns.
        clauses: Vec<Clause>,
    },
    /// `ALTER TABLE` with embedding clauses or column changes.
    AlterTable {
        /// The database, when the statement names one.
        db: Option<String>,
        /// The table.
        table: String,
        /// The specifications that matter, in order.
        specs: Vec<Spec>,
    },
}

impl Stmt {
    /// Whether the statement has an embedding clause.
    #[must_use]
    pub fn declares(&self) -> bool {
        match self {
            Stmt::CreateTable { clauses, .. } => !clauses.is_empty(),
            Stmt::AlterTable { specs, .. } => specs
                .iter()
                .any(|s| matches!(s, Spec::Add(_) | Spec::Modify(_))),
        }
    }
}

/// The settings an embedded column's hidden source column carries in its
/// comment, so `SHOW CREATE TABLE` can print the clause from the table
/// alone.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Meta {
    /// The embedded column.
    pub column: String,
    /// The model alias.
    pub model: String,
    /// The generation.
    pub generation: u32,
    /// `ON CHANGE`.
    pub mode: Mode,
    /// `WITH (max_input_tokens = n)`.
    pub max_input_tokens: Option<u32>,
    /// A shadow generation's source, not yet in use.
    pub shadow: bool,
}

impl Meta {
    /// The comment text: [`COMMENT_TAG`] and a JSON object.
    #[must_use]
    pub fn comment(&self) -> String {
        let mut v = json!({
            "column": self.column,
            "model": self.model,
            "generation": self.generation,
            "mode": self.mode.as_str(),
        });
        if let Some(n) = self.max_input_tokens {
            v["max_input_tokens"] = json!(n);
        }
        if self.shadow {
            v["shadow"] = json!(true);
        }
        format!("{COMMENT_TAG}{v}")
    }

    /// From [`Meta::comment`]'s text.
    #[must_use]
    pub fn from_comment(text: &str) -> Option<Self> {
        let v: Value = serde_json::from_str(text.strip_prefix(COMMENT_TAG)?).ok()?;
        Some(Self {
            column: v["column"].as_str()?.to_owned(),
            model: v["model"].as_str()?.to_owned(),
            generation: u32::try_from(v["generation"].as_u64()?).ok()?,
            mode: Mode::parse(v["mode"].as_str().unwrap_or("async"))?,
            max_input_tokens: v["max_input_tokens"]
                .as_u64()
                .and_then(|n| u32::try_from(n).ok()),
            shadow: v["shadow"].as_bool().unwrap_or(false),
        })
    }
}

/// A string literal for MariaDB with the default `sql_mode`; the texts
/// quoted here hold no backslashes ([`check_names`]).
fn lit(s: &str) -> String {
    format!("'{}'", s.replace('\'', "''"))
}

/// A quoted identifier.
#[must_use]
pub fn quote(s: &str) -> String {
    format!("`{}`", s.replace('`', "``"))
}

/// The column definitions for a clause: the vector column (for the current
/// generation, visible; for a shadow, hidden), the hidden source column
/// (left out for a shadow whose source is the current one's, `with_src`
/// false) and the hidden hash column.
#[must_use]
pub fn column_defs(
    column: &str,
    dim: u32,
    source: &str,
    meta: &Meta,
    shadow: Option<u32>,
    with_src: bool,
) -> Vec<String> {
    let mut out = Vec::with_capacity(3);
    let hidden = if shadow.is_some() { " INVISIBLE" } else { "" };
    out.push(format!(
        "{} VECTOR({dim}) NULL DEFAULT NULL{hidden}",
        quote(&vector_column(column, shadow))
    ));
    if with_src {
        out.push(format!(
            "{} MEDIUMTEXT GENERATED ALWAYS AS ({source}) VIRTUAL INVISIBLE COMMENT {}",
            quote(&src_column(column, shadow)),
            lit(&meta.comment())
        ));
    }
    out.push(format!(
        "{} BINARY(16) NULL DEFAULT NULL INVISIBLE",
        quote(&hash_column(column, shadow))
    ));
    out
}

/// The statement with each span replaced by its text (spans must not
/// overlap).
#[must_use]
pub fn splice(sql: &str, mut edits: Vec<(Range<usize>, String)>) -> String {
    edits.sort_by_key(|(r, _)| r.start);
    let mut out = String::with_capacity(sql.len() + 256);
    let mut at = 0;
    for (r, text) in edits {
        if r.start < at || r.end > sql.len() {
            continue;
        }
        out.push_str(&sql[at..r.start]);
        out.push_str(&text);
        at = r.end;
    }
    out.push_str(&sql[at..]);
    out
}

/// The cutover of a re-embedding to generation `to` on one table: the
/// shadow's vector and hash columns take the current ones' names (the
/// vector column at the old one's place, after `after`, or first), and the
/// source column becomes the shadow's (when `new_source` is given) or keeps
/// its expression with the new generation's comment. One statement, so
/// readers see the old vectors or the new ones, never a mix within the
/// table. Without a new source, MariaDB does it in place (`INSTANT`).
#[must_use]
#[allow(clippy::too_many_arguments)] // one per part of the statement
pub fn cutover_sql(
    table: &str,
    column: &str,
    to: u32,
    dim: u32,
    after: Option<&str>,
    source: &str,
    new_source: bool,
    meta: &Meta,
) -> String {
    let c = quote(column);
    let place = after.map_or_else(|| " FIRST".to_owned(), |a| format!(" AFTER {}", quote(a)));
    let mut s = format!(
        "ALTER TABLE {table} DROP COLUMN {c}, DROP COLUMN {}, CHANGE COLUMN {} {c} VECTOR({dim}) NULL DEFAULT NULL{place}, CHANGE COLUMN {} {} BINARY(16) NULL DEFAULT NULL INVISIBLE",
        quote(&hash_column(column, None)),
        quote(&vector_column(column, Some(to))),
        quote(&hash_column(column, Some(to))),
        quote(&hash_column(column, None)),
    );
    let comment = lit(&meta.comment());
    if new_source {
        let _ = write!(
            s,
            ", DROP COLUMN {}, CHANGE COLUMN {} {} MEDIUMTEXT GENERATED ALWAYS AS ({source}) VIRTUAL INVISIBLE COMMENT {comment}",
            quote(&src_column(column, None)),
            quote(&src_column(column, Some(to))),
            quote(&src_column(column, None)),
        );
    } else {
        let _ = write!(
            s,
            ", MODIFY COLUMN {} MEDIUMTEXT GENERATED ALWAYS AS ({source}) VIRTUAL INVISIBLE COMMENT {comment}",
            quote(&src_column(column, None)),
        );
    }
    s
}

/// `ALTER TABLE` specifications dropping a shadow generation's hidden
/// columns (an abandoned re-embedding).
#[must_use]
pub fn drop_shadow_specs(column: &str, generation: u32, with_src: bool) -> Vec<String> {
    let mut v = vec![
        format!(
            "DROP COLUMN IF EXISTS {}",
            quote(&vector_column(column, Some(generation)))
        ),
        format!(
            "DROP COLUMN IF EXISTS {}",
            quote(&hash_column(column, Some(generation)))
        ),
    ];
    if with_src {
        v.push(format!(
            "DROP COLUMN IF EXISTS {}",
            quote(&src_column(column, Some(generation)))
        ));
    }
    v
}

// ---- parsing ------------------------------------------------------------------

/// The statement's meaningful tokens.
struct Toks<'a> {
    sql: &'a [u8],
    t: Vec<Token>,
    no_backslash_escapes: bool,
}

impl Toks<'_> {
    fn word(&self, j: usize, w: &str) -> bool {
        self.t.get(j).is_some_and(|tk| {
            tk.kind == TokenKind::Word && tk.bytes(self.sql).eq_ignore_ascii_case(w.as_bytes())
        })
    }

    fn punct(&self, j: usize, c: u8) -> bool {
        self.t.get(j).is_some_and(|tk| {
            matches!(tk.kind, TokenKind::Punct | TokenKind::Op) && tk.bytes(self.sql) == [c]
        })
    }

    fn ident(&self, j: usize) -> Option<String> {
        self.t
            .get(j)
            .filter(|tk| tk.kind.is_ident_like())
            .map(|tk| String::from_utf8_lossy(&lex::ident_value(tk.bytes(self.sql))).into_owned())
    }

    fn string(&self, j: usize) -> Option<String> {
        self.t
            .get(j)
            .filter(|tk| tk.kind == TokenKind::String)
            .and_then(|tk| lex::string_value(tk.bytes(self.sql), self.no_backslash_escapes))
            .map(|b| String::from_utf8_lossy(&b).into_owned())
    }

    fn number(&self, j: usize) -> Option<u32> {
        self.t
            .get(j)
            .filter(|tk| tk.kind == TokenKind::Number)
            .and_then(|tk| std::str::from_utf8(tk.bytes(self.sql)).ok()?.parse().ok())
    }

    /// The `)` matching the `(` at `from`.
    fn matching(&self, from: usize) -> Option<usize> {
        let mut d = 0i32;
        for k in from..self.t.len() {
            if self.punct(k, b'(') {
                d += 1;
            } else if self.punct(k, b')') {
                d -= 1;
                if d == 0 {
                    return Some(k);
                }
            }
        }
        None
    }

    /// Token ranges `[a, b)` split at top-level commas.
    fn split(&self, a: usize, b: usize) -> Vec<(usize, usize)> {
        let mut out = Vec::new();
        let mut d = 0i32;
        let mut start = a;
        for k in a..b {
            if self.punct(k, b'(') {
                d += 1;
            } else if self.punct(k, b')') {
                d -= 1;
            } else if d == 0 && self.punct(k, b',') {
                out.push((start, k));
                start = k + 1;
            }
        }
        out.push((start, b));
        out
    }

    /// The bytes of tokens `[a, b]`.
    fn range(&self, a: usize, b: usize) -> Range<usize> {
        self.t[a].start as usize..self.t[b].end as usize
    }

    fn text(&self, a: usize, b: usize) -> String {
        String::from_utf8_lossy(&self.sql[self.range(a, b)]).into_owned()
    }

    /// `[db.]name` at `j`: (db, name, next token).
    fn table_name(&self, j: usize) -> Option<(Option<String>, String, usize)> {
        let first = self.ident(j)?;
        if self.punct(j + 1, b'.') {
            let second = self.ident(j + 2)?;
            Some((Some(first), second, j + 3))
        } else {
            Some((None, first, j + 1))
        }
    }

    /// `GENERATED BY EMBEDDING` starting at `j`.
    fn embedding_at(&self, j: usize) -> bool {
        self.word(j, "GENERATED") && self.word(j + 1, "BY") && self.word(j + 2, "EMBEDDING")
    }

    fn mentions_embedding(&self, a: usize, b: usize) -> bool {
        (a..b).any(|j| self.embedding_at(j))
    }
}

/// `c VECTOR(n) [NULL] GENERATED BY EMBEDDING(src) USING MODEL 'm'
/// [ON CHANGE ASYNC|SYNC] [WITH (max_input_tokens = n)]` over tokens
/// `[a, b)`, `span` its text.
#[allow(clippy::too_many_lines, clippy::many_single_char_names)] // one step per part of the clause
fn clause(t: &Toks<'_>, a: usize, b: usize, span: Range<usize>) -> Result<Clause, String> {
    let column = t
        .ident(a)
        .ok_or_else(|| "an embedded column needs a name".to_owned())?;
    let mut j = a + 1;
    if !(t.word(j, "VECTOR") && t.punct(j + 1, b'(')) {
        return Err(format!(
            "embedded column {column} must be declared VECTOR(n), with n the model's dimensions"
        ));
    }
    let dim = t
        .number(j + 2)
        .filter(|_| t.punct(j + 3, b')'))
        .ok_or_else(|| format!("embedded column {column}: VECTOR needs its dimensions"))?;
    j += 4;
    if t.word(j, "NULL") {
        j += 1;
    }
    if !t.embedding_at(j) {
        let what = t.text(j.min(b.saturating_sub(1)), j.min(b.saturating_sub(1)));
        return Err(format!(
            "embedded column {column}: GENERATED BY EMBEDDING must follow VECTOR({dim}), not {what} (an embedded column is NULL until filled and takes no default)"
        ));
    }
    j += 3;
    if !t.punct(j, b'(') {
        return Err(format!(
            "embedded column {column}: EMBEDDING needs its source in parentheses"
        ));
    }
    let close = t
        .matching(j)
        .filter(|&c| c < b)
        .ok_or_else(|| format!("embedded column {column}: unbalanced parentheses"))?;
    if close == j + 1 {
        return Err(format!("embedded column {column}: the source is empty"));
    }
    let source = t.text(j + 1, close - 1);
    j = close + 1;
    if !(t.word(j, "USING") && t.word(j + 1, "MODEL")) {
        return Err(format!(
            "embedded column {column}: USING MODEL '<alias>' must follow the source"
        ));
    }
    let model = t
        .string(j + 2)
        .ok_or_else(|| format!("embedded column {column}: the model alias is a string"))?;
    j += 3;
    let mut mode = Mode::Async;
    let mut max_input_tokens = None;
    while j < b {
        if t.word(j, "ON") && t.word(j + 1, "CHANGE") {
            mode = if t.word(j + 2, "ASYNC") {
                Mode::Async
            } else if t.word(j + 2, "SYNC") {
                Mode::Sync
            } else {
                return Err(format!(
                    "embedded column {column}: ON CHANGE is ASYNC or SYNC"
                ));
            };
            j += 3;
        } else if t.word(j, "WITH") && t.punct(j + 1, b'(') {
            let close = t
                .matching(j + 1)
                .filter(|&c| c < b)
                .ok_or_else(|| format!("embedded column {column}: unbalanced parentheses"))?;
            for (x, y) in t.split(j + 2, close) {
                if x == y {
                    continue;
                }
                let key = t.ident(x).unwrap_or_default().to_ascii_lowercase();
                if key != "max_input_tokens" || !t.punct(x + 1, b'=') || y != x + 3 {
                    return Err(format!(
                        "embedded column {column}: WITH takes max_input_tokens = <n>, not {}",
                        t.text(x, y - 1)
                    ));
                }
                let n = t
                    .number(x + 2)
                    .filter(|&n| (1..=MAX_INPUT_TOKENS).contains(&n))
                    .ok_or_else(|| {
                        format!(
                            "embedded column {column}: max_input_tokens is a whole number from 1 to {MAX_INPUT_TOKENS}"
                        )
                    })?;
                max_input_tokens = Some(n);
            }
            j = close + 1;
        } else {
            return Err(format!(
                "embedded column {column}: unexpected {} after the embedding clause",
                t.text(j, j)
            ));
        }
    }
    Ok(Clause {
        column,
        dim,
        source,
        model,
        mode,
        max_input_tokens,
        span,
    })
}

/// Finds embedding clauses in `CREATE TABLE` and `ALTER TABLE`, and the
/// `ALTER TABLE` specifications that touch a column. `Ok(None)` for any
/// other statement, and for an `ALTER TABLE` touching no column.
///
/// # Errors
///
/// A malformed embedding clause, or one where it isn't allowed, with the
/// reason.
pub fn parse(sql: &[u8], opts: &LexOptions) -> Result<Option<Stmt>, String> {
    // Cheap test first: every statement that matters names a column
    // change or the clause.
    let Ok(all) = lex::lex(sql, opts) else {
        return Ok(None);
    };
    let t = Toks {
        sql,
        t: all.into_iter().filter(|k| !k.kind.is_trivia()).collect(),
        no_backslash_escapes: opts.no_backslash_escapes,
    };
    let n = t.t.len();
    // Statements with several parts aren't ours.
    let end = if t.punct(n.saturating_sub(1), b';') {
        n - 1
    } else {
        n
    };
    if (0..end).any(|j| t.punct(j, b';')) {
        return Ok(None);
    }
    if t.word(0, "CREATE") {
        return create_table(&t, end);
    }
    if t.word(0, "ALTER") {
        return alter_table(&t, end);
    }
    Ok(None)
}

fn create_table(t: &Toks<'_>, end: usize) -> Result<Option<Stmt>, String> {
    if !t.mentions_embedding(0, end) {
        return Ok(None);
    }
    let mut j = 1;
    if t.word(j, "OR") && t.word(j + 1, "REPLACE") {
        j += 2;
    }
    if t.word(j, "TEMPORARY") {
        return Err("a temporary table can't have embedded columns".into());
    }
    if !t.word(j, "TABLE") {
        return Ok(None);
    }
    j += 1;
    if t.word(j, "IF") && t.word(j + 1, "NOT") && t.word(j + 2, "EXISTS") {
        j += 3;
    }
    let (db, table, next) = t
        .table_name(j)
        .ok_or_else(|| "CREATE TABLE needs a table name".to_owned())?;
    if !t.punct(next, b'(') {
        return Err("embedded columns are declared in CREATE TABLE's column list".into());
    }
    let close = t
        .matching(next)
        .ok_or_else(|| "unbalanced parentheses".to_owned())?;
    if t.mentions_embedding(close, end) {
        return Err("GENERATED BY EMBEDDING belongs to a column definition".into());
    }
    let mut clauses = Vec::new();
    for (a, b) in t.split(next + 1, close) {
        if a < b && t.mentions_embedding(a, b) {
            clauses.push(clause(t, a, b, t.range(a, b - 1))?);
        }
    }
    Ok(Some(Stmt::CreateTable { db, table, clauses }))
}

#[allow(clippy::too_many_lines)] // one arm per verb
fn alter_table(t: &Toks<'_>, end: usize) -> Result<Option<Stmt>, String> {
    let mut j = 1;
    while t.word(j, "ONLINE") || t.word(j, "IGNORE") {
        j += 1;
    }
    if !t.word(j, "TABLE") {
        return Ok(None);
    }
    j += 1;
    if t.word(j, "IF") && t.word(j + 1, "EXISTS") {
        j += 2;
    }
    let Some((db, table, next)) = t.table_name(j) else {
        return Ok(None);
    };
    let mut specs = Vec::new();
    for (a, b) in t.split(next, end) {
        if a >= b {
            continue;
        }
        let span = t.range(a, b - 1);
        let mut k = a;
        let verb = ["ADD", "MODIFY", "CHANGE", "DROP", "RENAME", "ALTER"]
            .into_iter()
            .find(|w| t.word(a, w));
        let Some(verb) = verb else {
            if t.mentions_embedding(a, b) {
                return Err("GENERATED BY EMBEDDING belongs to ADD or MODIFY COLUMN".into());
            }
            continue;
        };
        k += 1;
        let column_word = t.word(k, "COLUMN");
        match verb {
            "ADD" | "MODIFY" => {
                if column_word {
                    k += 1;
                }
                let not_column = [
                    "INDEX",
                    "KEY",
                    "UNIQUE",
                    "PRIMARY",
                    "FOREIGN",
                    "CONSTRAINT",
                    "FULLTEXT",
                    "SPATIAL",
                    "VECTOR",
                    "CHECK",
                    "PARTITION",
                    "PERIOD",
                    "SYSTEM",
                ]
                .iter()
                .any(|w| t.word(k, w))
                    && !column_word;
                if t.word(k, "IF") {
                    // IF [NOT] EXISTS
                    k += if t.word(k + 1, "NOT") { 3 } else { 2 };
                }
                if t.mentions_embedding(a, b) {
                    if not_column || t.punct(k, b'(') {
                        return Err(
                            "declare each embedded column in its own ADD COLUMN or MODIFY COLUMN"
                                .into(),
                        );
                    }
                    let c = clause(t, k, b, span.clone())?;
                    specs.push(if verb == "ADD" {
                        Spec::Add(c)
                    } else {
                        Spec::Modify(c)
                    });
                } else if verb == "MODIFY"
                    && !not_column
                    && let Some(column) = t.ident(k)
                {
                    specs.push(Spec::Touch {
                        kind: Touch::Modify,
                        column,
                        span,
                    });
                }
            }
            "CHANGE" | "DROP" | "ALTER" => {
                if t.mentions_embedding(a, b) {
                    return Err("GENERATED BY EMBEDDING belongs to ADD or MODIFY COLUMN".into());
                }
                if column_word {
                    k += 1;
                } else if [
                    "INDEX",
                    "KEY",
                    "PRIMARY",
                    "FOREIGN",
                    "CONSTRAINT",
                    "CHECK",
                    "PARTITION",
                    "SYSTEM",
                    "PERIOD",
                    "UNIQUE",
                    "FULLTEXT",
                    "SPATIAL",
                    "VECTOR",
                ]
                .iter()
                .any(|w| t.word(k, w))
                {
                    continue;
                }
                if t.word(k, "IF") && t.word(k + 1, "EXISTS") {
                    k += 2;
                }
                if let Some(column) = t.ident(k) {
                    specs.push(Spec::Touch {
                        kind: match verb {
                            "CHANGE" => Touch::Change,
                            "DROP" => Touch::Drop,
                            _ => Touch::Alter,
                        },
                        column,
                        span,
                    });
                }
            }
            _ => {
                // RENAME COLUMN old TO new; RENAME [TO|AS] table and
                // RENAME INDEX don't touch a column.
                if column_word && let Some(column) = t.ident(k + 1) {
                    specs.push(Spec::Touch {
                        kind: Touch::Rename,
                        column,
                        span,
                    });
                }
            }
        }
    }
    if specs.is_empty() {
        return Ok(None);
    }
    Ok(Some(Stmt::AlterTable { db, table, specs }))
}

/// A column name an embedded column may have: letters, digits, `_` and
/// `$`, at most [`MAX_COLUMN`] characters, not starting `_sprig_`.
///
/// # Errors
///
/// Why the name can't be used.
pub fn check_column_name(column: &str) -> Result<(), String> {
    if column.is_empty()
        || column.len() > MAX_COLUMN
        || !column
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'$')
    {
        return Err(format!(
            "embedded column {column}: its name may have letters, digits, _ and $, at most {MAX_COLUMN} characters"
        ));
    }
    if column.to_ascii_lowercase().starts_with("_sprig_") {
        return Err(format!("'{column}' is a reserved name"));
    }
    Ok(())
}

/// Whether the statement names a reserved column or object (`_sprig_` or
/// `__sprig_`) anywhere: such a statement isn't rewritten with the hidden
/// columns allowed.
#[must_use]
pub fn names_reserved(sql: &[u8], opts: &LexOptions) -> bool {
    let Ok(all) = lex::lex(sql, opts) else {
        return true;
    };
    all.iter().any(|tk| {
        if !tk.kind.is_ident_like() {
            return false;
        }
        let v = lex::ident_value(tk.bytes(sql)).to_ascii_lowercase();
        v.starts_with(b"_sprig_") || v.starts_with(b"__sprig_")
    })
}

// ---- SHOW CREATE TABLE ------------------------------------------------------

/// The column name of a `SHOW CREATE TABLE` column line.
fn line_column(line: &str) -> Option<String> {
    let rest = line.trim_start().strip_prefix('`')?;
    let mut name = String::new();
    let mut chars = rest.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '`' {
            if chars.peek() == Some(&'`') {
                chars.next();
                name.push('`');
            } else {
                return Some(name);
            }
        } else {
            name.push(c);
        }
    }
    None
}

/// `(expr)` after `GENERATED ALWAYS AS ` and the comment of a hidden
/// source column's line.
fn src_parts(line: &str) -> Option<(String, String)> {
    let at = line.find(" GENERATED ALWAYS AS (")? + " GENERATED ALWAYS AS (".len();
    let bytes = line.as_bytes();
    let mut depth = 1i32;
    let mut k = at;
    let mut quote: Option<u8> = None;
    while k < bytes.len() {
        let c = bytes[k];
        match quote {
            Some(q) => {
                if c == b'\\' {
                    k += 1;
                } else if c == q {
                    quote = None;
                }
            }
            None => match c {
                b'\'' | b'"' | b'`' => quote = Some(c),
                b'(' => depth += 1,
                b')' => {
                    depth -= 1;
                    if depth == 0 {
                        break;
                    }
                }
                _ => {}
            },
        }
        k += 1;
    }
    let expr = line.get(at..k)?.to_owned();
    let c = line[k..].find(" COMMENT '")? + k + " COMMENT '".len();
    let tail = &line[c..];
    let mut comment = String::new();
    let mut it = tail.chars().peekable();
    while let Some(ch) = it.next() {
        match ch {
            '\'' if it.peek() == Some(&'\'') => {
                it.next();
                comment.push('\'');
            }
            '\'' => break,
            '\\' => {
                if let Some(n) = it.next() {
                    comment.push(n);
                }
            }
            other => comment.push(other),
        }
    }
    Some((expr, comment))
}

/// `SHOW CREATE TABLE`'s text with each embedded column's clause put back
/// on its line, from its hidden source column's comment. The hidden lines
/// themselves are left for the name layer to remove.
#[must_use]
pub fn show_create(text: &str) -> Cow<'_, str> {
    if !text.contains(COMMENT_TAG) {
        return Cow::Borrowed(text);
    }
    let lines: Vec<&str> = text.split('\n').collect();
    let mut clauses: Vec<(String, String)> = Vec::new();
    for l in &lines {
        let Some(name) = line_column(l) else {
            continue;
        };
        if !name.starts_with(PREFIX) || !name.ends_with("_src") {
            continue;
        }
        let Some((expr, comment)) = src_parts(l) else {
            continue;
        };
        let Some(meta) = Meta::from_comment(&comment) else {
            continue;
        };
        if meta.shadow || name != src_column(&meta.column, None) {
            continue;
        }
        let mut c = format!(
            " GENERATED BY EMBEDDING({expr}) USING MODEL {}",
            lit(&meta.model)
        );
        if meta.mode == Mode::Sync {
            c.push_str(" ON CHANGE SYNC");
        }
        if let Some(n) = meta.max_input_tokens {
            let _ = write!(c, " WITH (max_input_tokens = {n})");
        }
        clauses.push((meta.column, c));
    }
    if clauses.is_empty() {
        return Cow::Borrowed(text);
    }
    let out: Vec<String> = lines
        .iter()
        .map(|l| {
            let Some(name) = line_column(l) else {
                return (*l).to_owned();
            };
            let Some((_, c)) = clauses.iter().find(|(col, _)| *col == name) else {
                return (*l).to_owned();
            };
            let (body, comma) = match l.strip_suffix(',') {
                Some(b) => (b, ","),
                None => (*l, ""),
            };
            let body = body.strip_suffix(" DEFAULT NULL").unwrap_or(body);
            format!("{body}{c}{comma}")
        })
        .collect();
    Cow::Owned(out.join("\n"))
}

